// Merchant overview and focused collection views. Money and access stay in the shared domain.
export function renderHome(c) {
 const {state,shop:s,metrics:m,money,E,icon,time,soundPanel,shops}=c;
 const active=collectionQueue(state,s.id),receiver=c.receiver||{state:'muted',label:'Sound off',detail:'Set up this receiving phone.'};
 const latest=state.transactions.filter(t=>t.shopId===s.id).sort((a,b)=>Date.parse(b.confirmedAt||b.createdAt)-Date.parse(a.confirmedAt||a.createdAt)).slice(0,4);
 const refunded=t=>state.refunds.filter(r=>r.transactionId===t.id&&r.status==='paid').reduce((v,r)=>v+r.amount,0),total=money(m.currentNet);
 return `<div class="merchant-home"><header class="home-heading"><h1>Home</h1><label class="home-shop-selector"><span class="sr-only">Collecting at</span><span class="home-shop-name" aria-hidden="true">${E(s.name)}</span>${icon('down')}<select data-change="collectShop" aria-label="Shop receiving this payment">${shops.map(sh=>`<option value="${E(sh.id)}" ${s.id===sh.id?'selected':''}>${E(sh.name)}</option>`).join('')}</select></label></header>
 <section class="home-summary" aria-label="Shop collections since last close"><div class="home-net"><small>Net collected · since last close</small><strong class="${total.length>14?'is-wide':total.length>11?'is-long':''}">${total}</strong></div><div class="home-summary-details"><div><span class="sr-only">Confirmed payments</span><strong>${m.currentCount}</strong><span> received</span></div><div><span class="sr-only">Still processing</span><strong>${money(m.pending)}</strong><span> processing</span></div></div></section>
 ${shopWarning(c)}${receiverAttention(c)}
 <div class="home-actions"><button class="home-collect btn primary" data-action="collect-shortcut" data-mode="amount">Collect payment</button><button class="btn secondary home-shop-qr" data-action="collect-shortcut" data-mode="static">Shop QR</button></div>
 <div class="mobile-quick-status home-quick-status"><button class="text-btn receiver-state ${E(receiver.state)}" data-action="sound-settings" aria-label="Receiving phone: ${E(receiver.label)}. ${E(receiver.detail)}">${icon(receiver.state==='ready'?'sound':'mute')} <span>${E(receiver.label)}</span></button><button class="text-btn" data-action="collection-requests">${icon('clock')} Requests <strong>${active.length}</strong></button></div>
 <div class="home-activity"><section class="collect-receipts"><header><h2>Latest payments</h2><button class="text-btn" data-action="go-activity">View all ${icon('arrow')}</button></header>${latest.length?latest.map(t=>`<button class="collect-receipt" data-action="transaction" data-id="${E(t.id)}"><span class="transaction-avatar">${icon(t.status==='paid'?'check':'clock')}</span><span><strong>${E(t.payer)}</strong><small>${time(t.confirmedAt||t.createdAt)} · ${t.status==='paid'?(refunded(t)>=t.amount?'Refunded':refunded(t)>0?'Part refunded':'Confirmed'):E(t.status)}</small></span><strong>${money(t.amount)}</strong></button>`).join(''):'<div class="collect-tip">Your first confirmed payment will appear here.</div>'}</section></div>
 <div class="home-panels"><details class="home-panel" data-home-panel="requests"><summary><span>Payment requests</span><span class="home-panel-meta">${active.length}${icon('down')}</span></summary><section class="collect-requests">${active.length?active.slice(0,3).map(r=>`<button class="collect-request" data-action="request-detail" data-id="${E(r.id)}">${icon('qr')}<span><strong>${money(r.amount)}</strong><small>${requestPresentation(state,r).status==='processing'?'Checking payment':'Waiting for payment'} · ${E(r.description||'Payment request')}</small></span>${icon('chevron')}</button>`).join(''):'<p>No open requests. Ready for your next customer.</p>'}${active.length>3?'<button class="text-btn" data-action="collection-requests">View all requests</button>':''}</section></details>
 <details class="home-panel" data-home-panel="receiver"><summary><span>Your receiving phone</span><span class="home-panel-meta">${E(receiver.label)}${icon('down')}</span></summary><section class="receiver-strip home-receiver">${soundPanel()}<button class="text-btn" data-action="sound-settings">Set up announcements ${icon('arrow')}</button></section></details></div></div>`;
}

export function renderCollections(c) {
 const {state,ui,shop:s,money,E,icon,qrSvg,paymentLink,submitting}=c;
 const live=s.accepting&&s.open!==false,mode=ui.collectMode||'amount';
 const confirmed=state.transactions.filter(t=>t.shopId===s.id&&t.status==='paid').sort((a,b)=>Date.parse(b.confirmedAt||b.createdAt)-Date.parse(a.confirmedAt||a.createdAt))[0];
 const receipt=confirmed&&mode==='static'?confirmed:null;
 return `<header class="collect-focused-heading"><h1>Collect payment</h1><button class="collect-current-shop" data-action="go-home" aria-label="Change receiving shop. Currently ${E(s.name)}">${icon('shops')}<span>${E(s.name)}</span>${icon('down')}</button></header>
 ${c.shared===false?`<div class="callout warning">${icon('shield')}<span><strong>Browser-only sample.</strong> Its QR and shop code cannot receive payments from the Lumo consumer app.</span><button class="text-btn" data-action="onboarding">Create merchant account ${icon('arrow')}</button></div>`:''}${shopWarning(c)}${receipt?receivedCard(c,receipt):''}
 <div class="collect-layout"><section class="collect-terminal" aria-label="Receive a payment"><div class="collect-tabs" role="group" aria-label="Choose QR type"><button class="${mode==='amount'?'active':''}" data-action="collect-mode" data-mode="amount" aria-pressed="${mode==='amount'}">${icon('qr')}Enter amount</button><button class="${mode==='static'?'active':''}" data-action="collect-mode" data-mode="static" aria-pressed="${mode==='static'}">${icon('shops')}Shop QR</button></div>
 ${mode==='amount'?`<div class="collect-amount"><small>Amount to receive · GH₵</small><strong aria-live="polite" aria-label="${E(ui.charge||'0.00')} Ghana cedis">${E(ui.charge||'0.00')}<span class="amount-caret"></span></strong></div><label class="collect-note"><input id="collection-note" value="${E(ui.collectionNote||'')}" placeholder="Add a note (optional)" maxlength="80" aria-label="Payment note, optional" data-change="collectionNote" ${c.pending||submitting?'readonly':''}></label><div class="collect-keypad">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(n=>`<button data-action="key" data-value="${n}" aria-label="${n==='⌫'?'Delete digit':n==='.'?'Decimal point':n}">${n==='⌫'?icon('back'):n}</button>`).join('')}</div><button class="collect-generate btn primary full" data-action="create-charge" ${!Number(ui.charge)||(!live&&!c.pending)||submitting?'disabled':''}>${submitting?'Creating QR…':c.pending?'Retrieve payment QR':'Generate payment QR'} ${icon('arrow')}</button><button class="text-btn share-collect-entry" data-action="share-payment-link" data-id="${E(s.id)}" data-amount="draft">${icon('link')} Share payment link</button><div class="collect-terminal-foot"><span>${icon('shield')} Customer pays the exact amount</span>${ui.charge?'<button class="text-btn" data-action="clear-charge">Clear</button>':''}</div>`:
 `<div class="static-collection"><div class="static-title"><h2>Your shop. One QR.</h2><p>${c.shared===false?'Preview a sample payment in this browser.':'Customer scans, enters the amount and pays.'}</p></div><div class="static-qr">${qrSvg(paymentLink(s.id))}</div><strong>${E(state.business.name)}</strong><p class="static-shop-code">${E(s.name)} · ${E(s.code)}</p><p class="static-instructions">${c.shared===false?'Use Preview customer payment to explore this sample.':'Keep this QR at your counter. Use it again and again.'}</p><div class="static-actions"><button class="btn primary" data-action="download-poster" data-id="${E(s.id)}">${icon('download')} Save QR poster</button><button class="btn secondary" data-action="share-payment-link" data-id="${E(s.id)}">${icon('link')} Share payment link</button></div>${c.shared===false?`<button class="text-btn" data-action="student-pay" data-id="${E(s.id)}">Preview customer payment ${icon('arrow')}</button>`:`<a class="text-btn" href="${E(paymentLink(s.id))}" target="_blank" rel="noopener">Open in Lumo ${icon('arrow')}</a>`}</div>`}</section></div>`;
}

function shopWarning(c) {
 const {shop:s,icon}=c;
 return !s.accepting||s.open===false?`<div class="callout warning">${icon('clock')}<span>This shop is ${s.open===false?'closed':'paused'}. Open it in Administration before collecting.</span><button class="text-btn" data-action="go-shop-operations">Shop controls ${icon('arrow')}</button></div>`:'';
}

function receiverAttention(c) {
 const {receiver,E}=c;
 return receiver&&['failed','offline'].includes(receiver.state)?`<div class="receiver-attention ${E(receiver.state)}" role="alert"><span>${E(receiver.detail)}</span><button class="text-btn" data-action="sound-settings">${receiver.state==='failed'?'Retest sound':'Check connection'}</button></div>`:'';
}

function receivedCard(c,receipt) {
 const {money,E,icon,time}=c;
 return `<button class="collection-received ${c.freshReceiptId===receipt.id?'new-receipt':''}" data-action="transaction" data-id="${E(receipt.id)}" aria-label="Confirmed payment ${money(receipt.amount)} from ${E(receipt.payer)}, ${E(c.receiptWhen?.(receipt)||time(receipt.confirmedAt||receipt.createdAt))}. View receipt"><span class="collection-received-check">${icon('check')}</span><span><small>${c.freshReceiptId===receipt.id?'Payment received':'Last confirmed payment'}</small><strong>${money(receipt.amount)}</strong><span>${E(receipt.payer)} · ${E(c.receiptWhen?.(receipt)||time(receipt.confirmedAt||receipt.createdAt))}</span></span>${icon('chevron')}</button>`;
}

export function renderAdministration(c) {
 const {ui,state,metrics:m,money,E,icon}=c,owner=ui.role==='owner',manager=ui.role==='manager';
 const groups=owner?[
 ['Your money',[['overview','wallet','Business overview','All shops and your merchant balance'],['activity','payments','Payments & refunds','Receipts, pending payments and returns'],['approvals','refund','Refund approvals',`${state.refunds.filter(r=>r.status==='requested').length} awaiting your decision`],['settlements','settlements','Settle to bank','Manage your settlement destination'],['reports','reports','Reports & daily close','Trading days, operators and exports'],['business-plan','wallet','Business plan','Stock, upcoming expenses and money after your plan'],['payment-links','link','Shared payment links','Check online links and confirmed collections']]],
 ['Your business',[['shops','shops','Shops','Locations, shop QRs and collections'],['team','team','Team & access','Staff, invitations and permissions'],['activation','check','Get a shop ready','Set up your next receiving counter'],['shop-operations','clock','Run this shop','Opening hours, shifts and daily close']]],
 ['Tools & support',[['devices','sound','Receiving phones','Pair a phone and test announcements'],['operations','shield','Operations','Exceptions, reconciliation and cases'],['lux','spark','Ask Lux','Understand your collection records'],['settings','settings','Business settings','Business details and preferences'],['support','help','Help & support','Track and raise a support case']]]
 ]:manager?[
 ['This shop',[['overview','shops','Shop overview','Your shop’s collections and activity'],['activity','payments','Payments & refunds','Receipts and customer returns'],['shop-operations','clock','Run this shop','Opening hours, shifts and handover'],['close','reports','Close shop day','Close collections without moving funds'],['reports','reports','Reports','Shop performance and exports'],['business-plan','wallet','Business plan','View planning when the owner allows access'],['payment-links','link','Shared payment links','Payment links available to your shop'],['team','team','Shop team','People assigned to this shop']]],
 ['Tools & support',[['devices','sound','Receiving phones','Pair a phone and test announcements'],['activation','check','Shop readiness','Check your counter setup'],['lux','spark','Ask Lux','Understand your collection records'],['support','help','Help & support','Raise and track a support case']]]
 ]:[['Your counter',[['activity','payments','Payment history','Receipts and refund requests'],['shop-operations','clock','Shift & handover','Your shop’s shift controls'],['devices','sound','Receiving phones','Pair your phone and test the sound'],['activation','check','Shop readiness','Check your counter setup'],['support','help','Help & support','Get help with a payment']]]];
 if(manager&&state.businessPlanAccess?.canView!==true)for(const group of groups)group[1]=group[1].filter(tool=>tool[0]!=='business-plan');
 if(c.registered)groups.push(['Your account',[['security','shield','Account & security','Profile, password and signed-in devices']]]);
 return `<div class="admin-intro"><div class="eyebrow">ADMINISTRATION</div><h1>Your business, in view.</h1><p>${owner?'Everything behind the counter, in one place.':`Tools for ${E(c.shop.name)}. Your access follows your role.`}</p></div><section class="admin-balance"><div><small>${owner?'Merchant balance · all shops':'Net shop collections · since last close'}</small><strong>${money(owner?m.balance:c.shopMetrics.currentNet)}</strong><p>${owner?'One account. Every shop connected.':'Closing the shop day keeps merchant funds intact.'}</p></div>${owner?`<button class="btn light" data-action="go-settlements">Settle funds ${icon('arrow')}</button>`:`<button class="btn light" data-action="go-checkout">Collect payment ${icon('qr')}</button>`}</section><div class="admin-groups">${groups.map(([title,tools])=>`<section class="admin-group"><h2>${title}</h2><div class="admin-tools">${tools.map(([page,i,label,note])=>`<button class="admin-tool" data-action="${page==='approvals'?'approvals':'nav'}" data-page="${page}"><span class="admin-tool-icon">${icon(i)}</span><span><strong>${label}${page==='approvals'&&state.refunds.some(r=>r.status==='requested')?` <span class="admin-approval-count">${state.refunds.filter(r=>r.status==='requested').length}</span>`:''}</strong><small>${note}</small></span>${icon('chevron')}</button>`).join('')}</div></section>`).join('')}</div>`;
}

export function requestPresentation(state,request,now=Date.now()) {
 const transaction=state.transactions.find(t=>t.requestId===request.id&&t.status==='paid')||null;
 const processing=state.transactions.find(t=>t.requestId===request.id&&t.status==='processing')||null;
 const status=transaction?'paid':processing?'processing':request.status!=='open'?request.status:Date.parse(request.expiresAt)<=now?'expired':'waiting';
 return {status,transaction,processing,canPay:status==='waiting',remaining:Math.max(0,Math.ceil((Date.parse(request.expiresAt)-now)/1000))};
}

export function collectionQueue(state,shopId,now=Date.now()) {
 return state.requests.filter(request=>request.shopId===shopId&&['waiting','processing'].includes(requestPresentation(state,request,now).status));
}

export function newConfirmedReceipts(transactions,known) {
 const positions=new Map(transactions.map((payment,index)=>[payment.id,index]));
 return transactions.filter(payment=>payment.status==='paid'&&!known.has(payment.id)).sort((a,b)=>Date.parse(a.confirmedAt||a.createdAt)-Date.parse(b.confirmedAt||b.createdAt)||positions.get(b.id)-positions.get(a.id));
}
